    // Null check: if either array is null, they cannot be equal for any positive count.
    if (a == null || b == null) {
        return false;
    }
    // Zero count means nothing to compare – trivially equal.
    if (count <= 0) {
        return true;
    }
    // If count exceeds either array length, the comparison cannot succeed.
    if (count > a.length || count > b.length) {
        return false;
