    if (node == null) return false;
    try{
        // Detach node from its neighbors
        ListNodeImpl<E> prev = node.prev;
        ListNodeImpl<E> next = node.next;

        if (prev != null) {
            prev.next = next;
        } else {
            // node is the first element
            head = next;
