public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int len = arr.length;
    if (from < 0 || to >= len || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to + ", length=" + len);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

