private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    /* No-op if the same list */
    if (this == list) {
        return;
    }
    /* Acquire locks in a consistent order to prevent dead‑lock. */
    Object firstLock = System.identityHashCode(this) < System.identityHashCode(list) ? this : list;
    Object secondLock = firstLock == this ? list : this;
    synchronized (firstLock) {
        synchronized (secondLock) {
            /* If the source list is empty there is nothing to move */
            if (list.size == 0 || list.head == null) {
                return;
            }
            /* Reconnect tails and heads */
            if (this.tail == null) {            // destination is empty
                this.head = list.head;
                this.tail = list.tail;
            } else {                            // destination non‑empty
                this.tail.next = list.head;
                list.head.prev = this.tail;
                this.tail = list.tail;
            }
            /* Update sizes */
            this.size += list.size;
            /* Reset the source list to empty */
            list.head = null;
            list.tail = null;
            list.size = 0;
        }
    }
}

