    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap must not be null.");
    }
    try {
        java.util.List<V> left = new java.util.ArrayList<>();
        java.util.List<V> right = new java.util.ArrayList<>();
        for (java.util.Map.Entry<String, V> entry : resultMap.entrySet()) {
            String key = entry.getKey();
            V vertex = entry.getValue();
            if (key == null || vertex == null) {
                continue;
            }
            // Group vertices into two parts based on prefix. Default to left part if ambiguous.
            if (key.startsWith("U") || key.startsWith("L") || key.startsWith("A")) {
                left.add(vertex);
            } else if (key.startsWith("V") || key.startsWith("R") || key.startsWith("B")) {
                right.add(vertex);
            } else {
                left.add(vertex);
            }
        }
        for (V u : left) {
            for (V v : right) {
                try {
                    target.addEdge(u, v);
                } catch (Exception e) {
                    // Ignore or handle individually
                }
            }
        }
    } catch (Exception outer) {
        // Fallback: attempt to connect at least two vertices if available
        try {
            V first = null;
            V second = null;
            for (java.util.Map.Entry<String, V> entry : resultMap.entrySet()) {
