    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return bounds;
    }
    // create a sorted copy of keys
    List<K> sorted = new ArrayList<>(keys);
    // sort using natural ordering; cast to Comparable
    sorted.sort((a, b) -> ((Comparable<K>)a).compareTo(b));
    for (K key : keys){
        // binary search for key
        int idx = Collections.binarySearch(sorted, key, (a, b) -> ((Comparable<K>)a).compareTo(b));
        if (idx < 0){
            // insertion point is -(idx + 1)
            idx = -(idx + 1) - 1; // greatest index less than key
        } else {
            // key found; find previous element that is strictly less
            int i = idx - 1;
            while (i >= 0 && sorted.get(i).equals(key)){
                i--;
            }
            idx = i;
        }
        bounds.add(idx);
    }
    return bounds;
}

