private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    try {
        // Sorted copy of keys for computing lower bounds
        List<K> sorted = new ArrayList<>(keys);
        sorted.sort(Comparator.nullsLast((k1, k2) -> {
            if (k1 == null || k2 == null) return 0;
            if (!(k1 instanceof Comparable) || !(k2 instanceof Comparable)) return 0;
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) k1;
            return c1.compareTo(k2);
        }));
        Map<K, Integer> lowerMap = new HashMap<>();
        int maxSoFar = Integer.MIN_VALUE;
        for (K k : sorted){
            if (k == null){
                lowerMap.put(k, Integer.MIN_VALUE);
                continue;
            }
            lowerMap.put(k, maxSoFar);
            try{
                int val = ((Integer)k).intValue();
                if (val > maxSoFar){
                    maxSoFar = val;
                }
            }catch(ClassCastException e){
                // ignore non‑Integer keys
            }
        }
        for (K k : keys){
            result.add(lowerMap.getOrDefault(k, Integer.MIN_VALUE));
        }
    }catch(Exception e){
        // on any unexpected error return empty list
        result.clear();
    }
    return result;
}

