            }
        } else {
            stack.add(part);
        }
    }
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        result.append(stack.get(i));
        if (i < stack.size() - 1) {
            result.append("/");
        }
    }
    // Ensure at least '/' if result is empty
    if (result.length() == 0) {
        result.append("/");
    }
    return result.toString();
