public static int nextPrime(int desiredCapacity){
    // Handle invalid or small inputs
    if (desiredCapacity < 2) {
        return 2;
    }
    // Start from the desired capacity, adjust to odd if necessary
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    // Define an upper bound if desiredCapacity >= 1000 (within 11%)
    int upperBound = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        long temp = (long)desiredCapacity * 111L / 100L; // 1.11 * desiredCapacity
        if (temp > Integer.MAX_VALUE) {
            temp = Integer.MAX_VALUE;
        }
        upperBound = (int)temp;
        if (upperBound < candidate) {
            upperBound = candidate;
        }
    }
    try {
        while (candidate > 0 && candidate <= upperBound) {
            if (isPrime(candidate)) {
                return candidate;
            }
            candidate += 2; // Skip even numbers
        }
        // If we exit the loop within bounds without finding a prime, continue searching beyond bounds
        while (candidate > 0 && candidate != Integer.MIN_VALUE) {
            if (isPrime(candidate)) {
                return candidate;
            }
            // Prevent overflow
            if (candidate > Integer.MAX_VALUE - 2) {
                break;
            }
            candidate += 2;
        }
    } catch (Exception e) {
        // Fallback: return the closest valid integer
        return Math.max(2, Math.min(candidate, Integer.MAX_VALUE));
    }
    // Should not reach here; as a last resort return 2
    return 2;
}

