public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    try{
        if(str==null || session==null||lb==null){
            return lb;
        }
        int len = str.length();
        // UTF‑8 can use up to 3 bytes per character
        byte[] utf8 = new byte[len*3];
        int pos = 0;
        for(int i = 0; i < len; i++){
            char ch = str.charAt(i);
            if(ch >= 0x0001 && ch <= 0x007F){
                utf8[pos++] = (byte) ch;
            }else if(ch > 0x07FF){
                utf8[pos++] = (byte)(0xE0 | ((ch >> 12) & 0x0F));
                utf8[pos++] = (byte)(0x80 | ((ch >> 6) & 0x3F));
                utf8[pos++] = (byte)(0x80 | (ch & 0x3F));
            }else{
                utf8[pos++] = (byte)(0xC0 | ((ch >> 6) & 0x1F));
                utf8[pos++] = (byte)(0x80 | (ch & 0x3F));
            }
        }
        // Delegate actual writing to the session
        session.writeBytes(utf8, 0, pos);
        return lb;
    }catch(Exception e){
        // In case of unexpected errors, simply return the buffer as is
        return lb;
    }
}

